      "confidence": 0.9
    },
    {
      "category": "open_connection",
      "components": ["C3"],
      "pins": ["C3.1"],
      "nets": ["unconnected-(C3-Pad1)"],
      "observed": "C3 is a 0.1uF capacitor (Device:C) with pin 1 on the unconnected-(C3-Pad1) net and pin 2 on GND. Its footprint is an inductor footprint: Inductor_SMD:L_0805_2012Metric_Pad1.05x1.20mm_HandSolder.",
      "expected": "A capacitor should have both pins connected to the circuit it is intended to decouple or filter, and should use a capacitor footprint.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"C3\") (value \"0.1uF\") (footprint \"Inductor_SMD:L_0805_2012Metric_Pad1.05x1.20mm_HandSolder\") ... (libsource (lib \"Device\") (part \"C\") (description \"Unpolarized capacitor\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"59\") (name \"unconnected-(C3-Pad1)\") (class \"Default\") (node (ref \"C3\") (pin \"1\") (pintype \"passive\")))"
        }
      ],
      "impact": "C3 is electrically floating and provides no decoupling; the wrong footprint may also prevent proper assembly.",
      "confidence": 0.95
    }
  ],
  "summary": "The design files contain two anomalies: U3 pins 13 and 14 (Ethernet TX pair) are shorted to GND, and C3 is a floating 0.1uF capacitor with an inductor footprint."
}

